/// Raven `BotOrder`.
///
/// Source: `oracle/codemp/game/ai_main.c:184-276`
pub fn BotOrder(ctx: GameContext<'_>, ent: *mut gentity_t, clientnum: c_int, ordernum: c_int) {
    unsafe {
        let world = ctx.world;
        let base = (*world).g_entities.as_mut_ptr();
        let botstates = &(*world).globals.botstates;

        let mut stateMin: c_int = 0;
        let mut stateMax: c_int = 0;

        if ent.is_null()
            || (*ent).client.is_null()
            || (*((*ent).client as *mut gclient_t)).sess.teamLeader == qfalse
        {
            return;
        }

        if clientnum != -1 && botstates[clientnum as usize].is_null() {
            return;
        }

        if clientnum != -1 && OnSameTeam(ctx, ent, base.add(clientnum as usize)) == qfalse {
            return;
        }

        let gt = (*world).cvars.g_gametype.integer;
        if gt != GT_CTF && gt != GT_CTY && gt != GT_SIEGE && gt != GT_TEAM {
            return;
        }

        if gt == GT_CTF || gt == GT_CTY {
            stateMin = bot_ctf_state_t::CTFSTATE_NONE as c_int;
            stateMax = bot_ctf_state_t::CTFSTATE_MAXCTFSTATES as c_int;
        } else if gt == GT_SIEGE {
            stateMin = bot_siege_state_t::SIEGESTATE_NONE as c_int;
            stateMax = bot_siege_state_t::SIEGESTATE_MAXSIEGESTATES as c_int;
        } else if gt == GT_TEAM {
            stateMin = bot_teamplay_state_t::TEAMPLAYSTATE_NONE as c_int;
            stateMax = bot_teamplay_state_t::TEAMPLAYSTATE_MAXTPSTATES as c_int;
        }

        if (ordernum < stateMin && ordernum != -1) || ordernum >= stateMax {
            return;
        }

        if clientnum != -1 {
            let bi = botstates[clientnum as usize];
            if ordernum == -1 {
                BotReportStatus(ctx, bi);
            } else {
                BotStraightTPOrderCheck(base, ent, ordernum, bi);
                (*bi).state_Forced = ordernum;
                (*bi).chatObject = Some(ent_id(base, ent));
                (*bi).chatAltObject = None;
                let sect = cstr("OrderAccepted");
                if crate::ai_util::BotDoChat(ctx, bi, sect.as_ptr() as *mut c_char, 1) != 0 {
                    (*bi).chatTeam = 1;
                }
            }
        } else {
            let mut i: usize = 0;
            while i < MAX_CLIENTS {
                let bi = botstates[i];
                if !bi.is_null() && OnSameTeam(ctx, ent, base.add(i)) != qfalse {
                    if ordernum == -1 {
                        BotReportStatus(ctx, bi);
                    } else {
                        BotStraightTPOrderCheck(base, ent, ordernum, bi);
                        (*bi).state_Forced = ordernum;
                        (*bi).chatObject = Some(ent_id(base, ent));
                        (*bi).chatAltObject = None;
                        let sect = cstr("OrderAccepted");
                        if crate::ai_util::BotDoChat(ctx, bi, sect.as_ptr() as *mut c_char, 0) != 0
                        {
                            (*bi).chatTeam = 1;
                        }
                    }
                }
                i += 1;
            }
        }
    }
}

/// Raven `BotMindTricked`.
///
/// Source: `oracle/codemp/game/ai_main.c:279-325`
pub fn BotMindTricked(ctx: GameContext<'_>, botClient: c_int, enemyClient: c_int) -> c_int {
    unsafe {
        let world = &*ctx.world;
        let en = &world.g_entities[enemyClient as usize];
        if en.client.is_null() {
            return 0;
        }
        // Raven's `if (!fd)` guards `&ps.fd`, a member address that is never
        // null — a structurally dead check, dropped here.
        let fd = &(*(en.client as *mut gclient_t)).ps.fd;
        if botClient > 47 {
            if fd.forceMindtrickTargetIndex4 & (1 << (botClient - 48)) != 0 {
                return 1;
            }
        } else if botClient > 31 {
            if fd.forceMindtrickTargetIndex3 & (1 << (botClient - 32)) != 0 {
                return 1;
            }
        } else if botClient > 15 {
            if fd.forceMindtrickTargetIndex2 & (1 << (botClient - 16)) != 0 {
                return 1;
            }
        } else if fd.forceMindtrickTargetIndex & (1 << botClient) != 0 {
            return 1;
        }
        0
    }
}

