/// Raven `AngleDifference`.
///
/// Source: `oracle/codemp/game/ai_main.c:425-436`
pub fn AngleDifference(ang1: f32, ang2: f32) -> f32 {
    // Raven: signed shortest-arc difference between two yaw angles.
    let mut diff = ang1 - ang2;
    if ang1 > ang2 {
        if diff > 180.0 {
            diff -= 360.0;
        }
    } else if diff < -180.0 {
        diff += 360.0;
    }
    diff
}

/// Raven `BotChangeViewAngle`.
///
/// Source: `oracle/codemp/game/ai_main.c:443-463`
pub fn BotChangeViewAngle(angle: f32, ideal_angle: f32, speed: f32) -> f32 {
    let angle = crate::q_math::AngleMod(angle);
    let ideal_angle = crate::q_math::AngleMod(ideal_angle);
    if angle == ideal_angle {
        return angle;
    }
    let mut mv = ideal_angle - angle;
    if ideal_angle > angle {
        if mv > 180.0 {
            mv -= 360.0;
        }
    } else if mv < -180.0 {
        mv += 360.0;
    }
    if mv > 0.0 {
        if mv > speed {
            mv = speed;
        }
    } else if mv < -speed {
        mv = -speed;
    }
    crate::q_math::AngleMod(angle + mv)
}

/// Raven `BotChangeViewAngles`.
///
/// `PITCH`/`YAW` indices are 0/1 (Raven `q_shared.h`); no ported const module
/// exports them, so the literal indices are used with a note.
///
/// Source: `oracle/codemp/game/ai_main.c:470-530`
pub fn BotChangeViewAngles(ctx: GameContext<'_>, bs: *mut bot_state_t, thinktime: f32) {
    // `PITCH` (angle index) comes from the prelude (`crate::q_math::PITCH`).
    unsafe {
        let bs = &mut *bs;
        if bs.ideal_viewangles[PITCH] > 180.0 {
            bs.ideal_viewangles[PITCH] -= 360.0;
        }

        let mut factor: f32;
        if !bs.currentEnemy.is_none() && bs.frame_Enemy_Vis != 0 {
            if bs.settings.skill <= 1.0 {
                factor = (bs.skills.turnspeed_combat * 0.4) * bs.settings.skill;
            } else if bs.settings.skill <= 2.0 {
                factor = (bs.skills.turnspeed_combat * 0.6) * bs.settings.skill;
            } else if bs.settings.skill <= 3.0 {
                factor = (bs.skills.turnspeed_combat * 0.8) * bs.settings.skill;
            } else {
                factor = bs.skills.turnspeed_combat * bs.settings.skill;
            }
        } else {
            factor = bs.skills.turnspeed;
        }

        if factor > 1.0 {
            factor = 1.0;
        }
        if factor < 0.001 {
            factor = 0.001;
        }

        let mut maxchange = bs.skills.maxturn;
        maxchange *= thinktime;
        for i in 0..2usize {
            bs.viewangles[i] = crate::q_math::AngleMod(bs.viewangles[i]);
            bs.ideal_viewangles[i] = crate::q_math::AngleMod(bs.ideal_viewangles[i]);
            let diff = AngleDifference(bs.viewangles[i], bs.ideal_viewangles[i]);
            let disired_speed = diff * factor;
            bs.viewanglespeed[i] += bs.viewanglespeed[i] - disired_speed;
            if bs.viewanglespeed[i] > 180.0 {
                bs.viewanglespeed[i] = maxchange;
            }
            if bs.viewanglespeed[i] < -180.0 {
                bs.viewanglespeed[i] = -maxchange;
            }
            let mut anglespeed = bs.viewanglespeed[i];
            if anglespeed > maxchange {
                anglespeed = maxchange;
            }
            if anglespeed < -maxchange {
                anglespeed = -maxchange;
            }
            bs.viewangles[i] += anglespeed;
            bs.viewangles[i] = crate::q_math::AngleMod(bs.viewangles[i]);
            bs.viewanglespeed[i] =
                (bs.viewanglespeed[i] as f64 * (0.45 * (1.0 - factor) as f64)) as f32;
        }
        if bs.viewangles[PITCH] > 180.0 {
            bs.viewangles[PITCH] -= 360.0;
        }
        trap::EA_View(
            ctx.engine,
            BotlibEaViewArgs::new(bs.client, &bs.viewangles as *const vec3_t),
        );
    }
}

/// Raven `BotInputToUserCommand`.
///
/// Source: `oracle/codemp/game/ai_main.c:537-626`
pub fn BotInputToUserCommand(
    ctx: GameContext<'_>,
    bi: *mut bot_input_t,
    ucmd: *mut usercmd_t,
    delta_angles: *mut c_int,
    time: c_int,
    useTime: c_int,
) {
    // PORT-NOTE(ACTION_*/ANGLE2SHORT): the `ACTION_*` bot-input flag family
    // (be_ai_goal.h) and the `ANGLE2SHORT` macro have no ported home yet;
    // referenced as cited and reported as missing symbols.
    unsafe {
        let bi = &mut *bi;
        let ucmd = &mut *ucmd;

        // clear the whole structure
        core::ptr::write_bytes(ucmd as *mut usercmd_t, 0, 1);
        // the duration for the user command in milli seconds
        ucmd.serverTime = time;

        if bi.actionflags & ACTION_DELAYEDJUMP != 0 {
            bi.actionflags |= ACTION_JUMP;
            bi.actionflags &= !ACTION_DELAYEDJUMP;
        }
        // set the buttons
        if bi.actionflags & ACTION_RESPAWN != 0 {
            ucmd.buttons = BUTTON_ATTACK;
        }
        if bi.actionflags & ACTION_ATTACK != 0 {
            ucmd.buttons |= BUTTON_ATTACK;
        }
        if bi.actionflags & ACTION_ALT_ATTACK != 0 {
            ucmd.buttons |= BUTTON_ALT_ATTACK;
        }
        if bi.actionflags & ACTION_GESTURE != 0 {
            ucmd.buttons |= BUTTON_GESTURE;
        }
        if bi.actionflags & ACTION_USE != 0 {
            ucmd.buttons |= BUTTON_USE_HOLDABLE;
        }
        if bi.actionflags & ACTION_WALK != 0 {
            ucmd.buttons |= BUTTON_WALKING;
        }
        if bi.actionflags & ACTION_FORCEPOWER != 0 {
            ucmd.buttons |= BUTTON_FORCEPOWER;
        }

        if useTime < (*ctx.world).level.time && (*ctx.world).bg_state.rng.Q_irand(1, 10) < 5 {
            // for now just hit use randomly in case there's something useable around
            ucmd.buttons |= BUTTON_USE;
        }

        if bi.weapon == WP_NONE {
            bi.weapon = WP_BRYAR_PISTOL;
        }

        ucmd.weapon = bi.weapon as u8;
        // set the view angles (WITHOUT the delta angles)
        ucmd.angles[PITCH] = ANGLE2SHORT(bi.viewangles[PITCH]);
        ucmd.angles[YAW] = ANGLE2SHORT(bi.viewangles[YAW]);
        ucmd.angles[ROLL] = ANGLE2SHORT(bi.viewangles[ROLL]);
        // subtract the delta angles
        for j in 0..3usize {
            let temp: c_short = (ucmd.angles[j] - *delta_angles.add(j)) as c_short;
            ucmd.angles[j] = temp as c_int;
        }

        // movement is relative to the REAL view angles
        let mut angles: vec3_t = [0.0; 3];
        let mut forward: vec3_t = [0.0; 3];
        let mut right: vec3_t = [0.0; 3];
        if bi.dir[2] != 0.0 {
            angles[PITCH] = bi.viewangles[PITCH];
        } else {
            angles[PITCH] = 0.0;
        }
        angles[YAW] = bi.viewangles[YAW];
        angles[ROLL] = 0.0;
        crate::q_math::AngleVectors(angles, Some(&mut forward), Some(&mut right), None);
        // bot input speed is in the range [0, 400]
        bi.speed = bi.speed * 127.0 / 400.0;
        // set the view independent movement
        ucmd.forwardmove =
            (crate::q_math::_DotProduct(forward, bi.dir) * bi.speed) as c_int as c_schar;
        ucmd.rightmove = (crate::q_math::_DotProduct(right, bi.dir) * bi.speed) as c_int as c_schar;
        ucmd.upmove =
            ((forward[2] as c_int).abs() as f32 * bi.dir[2] * bi.speed) as c_int as c_schar;
        // normal keyboard movement
        if bi.actionflags & ACTION_MOVEFORWARD != 0 {
            ucmd.forwardmove = (ucmd.forwardmove as c_int + 127) as c_schar;
        }
        if bi.actionflags & ACTION_MOVEBACK != 0 {
            ucmd.forwardmove = (ucmd.forwardmove as c_int - 127) as c_schar;
        }
        if bi.actionflags & ACTION_MOVELEFT != 0 {
            ucmd.rightmove = (ucmd.rightmove as c_int - 127) as c_schar;
        }
        if bi.actionflags & ACTION_MOVERIGHT != 0 {
            ucmd.rightmove = (ucmd.rightmove as c_int + 127) as c_schar;
        }
        // jump/moveup
        if bi.actionflags & ACTION_JUMP != 0 {
            ucmd.upmove = (ucmd.upmove as c_int + 127) as c_schar;
        }
        // crouch/movedown
        if bi.actionflags & ACTION_CROUCH != 0 {
            ucmd.upmove = (ucmd.upmove as c_int - 127) as c_schar;
        }
    }
}

/// Raven `BotUpdateInput`.
///
/// Source: `oracle/codemp/game/ai_main.c:633-655`
pub fn BotUpdateInput(
    ctx: GameContext<'_>,
    bs: *mut bot_state_t,
    time: c_int,
    elapsed_time: c_int,
) {
    // PORT-NOTE(SHORT2ANGLE/ACTION_*): `SHORT2ANGLE` and the `ACTION_*` flags
    // have no ported home yet; referenced as cited and reported as missing.
    unsafe {
        let mut bi: bot_input_t = core::mem::zeroed();

        // add the delta angles to the bot's current view angles
        for j in 0..3usize {
            (*bs).viewangles[j] = crate::q_math::AngleMod(
                (*bs).viewangles[j] + SHORT2ANGLE((*bs).cur_ps.delta_angles[j]),
            );
        }
        // change the bot view angles
        BotChangeViewAngles(ctx, bs, elapsed_time as f32 / 1000.0);
        // retrieve the bot input
        trap::EA_GetInput(
            ctx.engine,
            BotlibEaGetInputArgs::new(
                (*bs).client,
                time as f32 / 1000.0,
                &mut bi as *mut bot_input_t as *mut c_void,
            ),
        );
        // respawn hack
        if bi.actionflags & ACTION_RESPAWN != 0 {
            if (*bs).lastucmd.buttons & BUTTON_ATTACK != 0 {
                bi.actionflags &= !(ACTION_RESPAWN | ACTION_ATTACK);
            }
        }
        // convert the bot input to a usercmd
        BotInputToUserCommand(
            ctx,
            &mut bi,
            &mut (*bs).lastucmd,
            (*bs).cur_ps.delta_angles.as_mut_ptr(),
            time,
            (*bs).noUseTime,
        );
        // subtract the delta angles
        for j in 0..3usize {
            (*bs).viewangles[j] = crate::q_math::AngleMod(
                (*bs).viewangles[j] - SHORT2ANGLE((*bs).cur_ps.delta_angles[j]),
            );
        }
    }
}

/// Raven `FloatTime()` (`#define FloatTime() floattime`).
///
/// `floattime` is a genuine Raven module-global (`ai_main.c:50`, `extern float
/// floattime` in `ai_main.h:410`) updated once per bot frame — narrower than the
/// `level`/`g_entities` state spine, so it is mirrored here as a monotonic
/// seconds clock via an atomic bit-store rather than threaded through
/// `GameContext`, matching the call sites' bare `FloatTime()` usage.
/// Source: `oracle/codemp/game/ai_main.c:663,665,871`; `ai_main.h:410-411`
static FLOATTIME_BITS: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

/// Raven `FloatTime()`.
///
/// Source: `oracle/codemp/game/ai_main.c:663,665,871`
pub fn FloatTime() -> f32 {
    f32::from_bits(FLOATTIME_BITS.load(core::sync::atomic::Ordering::Relaxed))
}

/// Raven `BotAIRegularUpdate`.
///
/// Source: `oracle/codemp/game/ai_main.c:662-667`
pub fn BotAIRegularUpdate(ctx: GameContext<'_>) {
    unsafe {
        let world = ctx.world;
        if (*world).globals.regularupdate_time < FloatTime() {
            trap::BotUpdateEntityItems(ctx.engine, BotlibAiUpdateEntityItemsArgs::new());
            (*world).globals.regularupdate_time = (FloatTime() as f64 + 0.3) as f32;
        }
    }
}

/// Raven `RemoveColorEscapeSequences`.
///
/// Source: `oracle/codemp/game/ai_main.c:674-688`
pub fn RemoveColorEscapeSequences(text: *mut c_char) {
    // Raven: strip Quake3 colour-escape pairs and drop bytes above 0x7E, in
    // place. `text[i]` is signed `char`, so `> 0x7E` catches only 0x7F (bytes
    // >=0x80 are negative) — faithful to the signed-char oracle behavior.
    unsafe {
        let mut i: isize = 0;
        let mut l: isize = 0;
        loop {
            let c = *text.offset(i);
            if c == 0 {
                break;
            }
            // Q_IsColorString inspects text[i] and text[i+1]; with c != 0 the
            // terminator guarantees text[i+1] is in-bounds.
            let pair = core::slice::from_raw_parts(text.offset(i) as *const u8, 2);
            if Q_IsColorString(pair) {
                i += 2;
                continue;
            }
            if c > 0x7E {
                i += 1;
                continue;
            }
            *text.offset(l) = c;
            l += 1;
            i += 1;
        }
        *text.offset(l) = 0;
    }
}

/// Raven `BotAI`.
///
/// Source: `oracle/codemp/game/ai_main.c:696-771`
pub fn BotAI(ctx: GameContext<'_>, client: c_int, thinktime: f32) -> c_int {
    // PORT-NOTE(botstates/PRT_FATAL/SHORT2ANGLE): `globals.botstates` is a `()`
    // placeholder (indexed as intended); `PRT_FATAL` and `SHORT2ANGLE` have no
    // ported home yet; the `_DEBUG` timing block is dropped (undefined here).
    unsafe {
        trap::EA_ResetInput(ctx.engine, BotlibEaResetInputArgs::new(client));
        let world = ctx.world;
        let bs = (*world).globals.botstates[client as usize];
        if bs.is_null() || (*bs).inuse == qfalse {
            let msg = format!("BotAI: client {} is not setup\n", client);
            BotAI_Print(PRT_FATAL, cstr(&msg).as_ptr() as *mut c_char);
            return qfalse;
        }

        // retrieve the current client state
        BotAI_GetClientState(ctx, client, &mut (*bs).cur_ps);

        // retrieve any waiting server commands
        let mut buf: [c_char; 1024] = [0; 1024];
        while trap::BotGetServerCommand(
            ctx.engine,
            BotlibGetConsoleMessageArgs::new(client, buf.as_mut_ptr(), 1024),
        ) != 0
        {
            // have buf point to the command and args to the command arguments
            let sp = b' ' as c_char;
            let mut k = 0usize;
            let mut args_ptr: *mut c_char = core::ptr::null_mut();
            while buf[k] != 0 {
                if buf[k] == sp {
                    args_ptr = buf.as_mut_ptr().add(k);
                    break;
                }
                k += 1;
            }
            if args_ptr.is_null() {
                continue;
            }
            *args_ptr = 0;
            let args = args_ptr.add(1);
            // remove color escape sequences from the arguments
            RemoveColorEscapeSequences(args);
            // Raven's Q_stricmp dispatch over "cp "/"cs"/"scores"/"clientLevelShot"
            // has empty bodies in MP — no observable effect, dropped.
        }
        // add the delta angles to the bot's current view angles
        for j in 0..3usize {
            (*bs).viewangles[j] = crate::q_math::AngleMod(
                (*bs).viewangles[j] + SHORT2ANGLE((*bs).cur_ps.delta_angles[j]),
            );
        }
        // increase the local time of the bot
        (*bs).ltime += thinktime;
        (*bs).thinktime = thinktime;
        // origin of the bot
        crate::q_math::_VectorCopy((*bs).cur_ps.origin, &mut (*bs).origin);
        // eye coordinates of the bot
        crate::q_math::_VectorCopy((*bs).cur_ps.origin, &mut (*bs).eye);
        (*bs).eye[2] += (*bs).cur_ps.viewheight as f32;

        StandardBotAI(ctx, bs, thinktime);

        // subtract the delta angles
        for j in 0..3usize {
            (*bs).viewangles[j] = crate::q_math::AngleMod(
                (*bs).viewangles[j] - SHORT2ANGLE((*bs).cur_ps.delta_angles[j]),
            );
        }
        qtrue
    }
}

/// Raven `BotScheduleBotThink`.
///
/// Source: `oracle/codemp/game/ai_main.c:778-791`
pub fn BotScheduleBotThink(ctx: GameContext<'_>) {
    unsafe {
        let world = ctx.world;
        let mut botnum: c_int = 0;
        for i in 0..MAX_CLIENTS {
            let bi = (*world).globals.botstates[i];
            if bi.is_null() || (*bi).inuse == qfalse {
                continue;
            }
            // initialize the bot think residual time
            (*bi).botthink_residual = BOT_THINK_TIME * botnum / (*world).globals.numbots;
            botnum += 1;
        }
    }
}

/// Raven `PlayersInGame`.
///
/// Source: `oracle/codemp/game/ai_main.c:793-812`
pub fn PlayersInGame(ctx: GameContext<'_>) -> c_int {
    unsafe {
        let world = &*ctx.world;
        let mut i: usize = 0;
        let mut pl = 0;
        while i < MAX_CLIENTS {
            let ent = &world.g_entities[i];
            if !ent.client.is_null()
                && (*(ent.client as *mut gclient_t)).pers.connected == CON_CONNECTED
            {
                pl += 1;
            }
            i += 1;
        }
        pl
    }
}

/// Raven `BotAISetupClient`.
///
/// Source: `oracle/codemp/game/ai_main.c:819-884`
pub fn BotAISetupClient(
    ctx: GameContext<'_>,
    client: c_int,
    settings: *mut bot_settings_t,
    restart: qboolean,
) -> c_int {
    // PORT-NOTE(botstates/PRT_FATAL): `globals.botstates` is a `()`
    // placeholder (indexed as intended); `PRT_FATAL` has no ported home yet.
    unsafe {
        let world = ctx.world;
        if (*world).globals.botstates[client as usize].is_null() {
            // `bot_state_t` holds `*mut wpobject_t` fields (align 8); pad the pool
            // to an 8-byte boundary first (see `BG_AllocPad8`) so every later
            // `(*bs).field` access is safely dereferenceable.
            crate::bg_misc::BG_AllocPad8(&mut (*world).bg_state);
            (*world).globals.botstates[client as usize] =
                crate::ai_util::B_Alloc(ctx, core::mem::size_of::<bot_state_t>() as c_int)
                    as *mut bot_state_t;
        }

        // C's `memset(bs, 0, sizeof(bot_state_t))` is byte-wise; BG_Alloc's bump
        // allocator only guarantees 4-byte alignment, not `bot_state_t`'s 8, so the
        // typed write_bytes (which checks pointee alignment) must not be used here.
        core::ptr::write_bytes(
            (*world).globals.botstates[client as usize] as *mut u8,
            0,
            core::mem::size_of::<bot_state_t>(),
        );

        let bs = (*world).globals.botstates[client as usize];

        if !bs.is_null() && (*bs).inuse != qfalse {
            let msg = format!("BotAISetupClient: client {} already setup\n", client);
            BotAI_Print(PRT_FATAL, cstr(&msg).as_ptr() as *mut c_char);
            return qfalse;
        }

        core::ptr::copy_nonoverlapping(settings, &mut (*bs).settings, 1);

        (*bs).client = client; // need the client number before personality stuff

        // initialize weapon weight defaults..
        (*bs).botWeaponWeights[WP_NONE as usize] = 0.0;
        (*bs).botWeaponWeights[WP_STUN_BATON as usize] = 1.0;
        (*bs).botWeaponWeights[WP_SABER as usize] = 10.0;
        (*bs).botWeaponWeights[WP_BRYAR_PISTOL as usize] = 11.0;
        (*bs).botWeaponWeights[WP_BLASTER as usize] = 12.0;
        (*bs).botWeaponWeights[WP_DISRUPTOR as usize] = 13.0;
        (*bs).botWeaponWeights[WP_BOWCASTER as usize] = 14.0;
        (*bs).botWeaponWeights[WP_REPEATER as usize] = 15.0;
        (*bs).botWeaponWeights[WP_DEMP2 as usize] = 16.0;
        (*bs).botWeaponWeights[WP_FLECHETTE as usize] = 17.0;
        (*bs).botWeaponWeights[WP_ROCKET_LAUNCHER as usize] = 18.0;
        (*bs).botWeaponWeights[WP_THERMAL as usize] = 14.0;
        (*bs).botWeaponWeights[WP_TRIP_MINE as usize] = 0.0;
        (*bs).botWeaponWeights[WP_DET_PACK as usize] = 0.0;
        (*bs).botWeaponWeights[WP_MELEE as usize] = 1.0;

        crate::ai_util::BotUtilizePersonality(ctx, bs);

        let gt = (*world).cvars.g_gametype.integer;
        if gt == GT_DUEL || gt == GT_POWERDUEL {
            (*bs).botWeaponWeights[WP_SABER as usize] = 13.0;
        }

        // allocate a goal state
        (*bs).gs = trap::BotAllocGoalState(ctx.engine, BotlibAiAllocGoalStateArgs::new(client));

        // allocate a weapon state
        (*bs).ws = trap::BotAllocWeaponState(ctx.engine, BotlibAiAllocWeaponStateArgs::new());

        (*bs).inuse = qtrue;
        (*bs).entitynum = client;
        (*bs).setupcount = 4;
        (*bs).entergame_time = FloatTime();
        (*bs).ms = trap::BotAllocMoveState(ctx.engine, BotlibAiAllocMoveStateArgs::new());
        (*world).globals.numbots += 1;

        // NOTE: reschedule the bot thinking
        BotScheduleBotThink(ctx);

        if PlayersInGame(ctx) != 0 {
            // don't talk to yourself
            let sect = cstr("GeneralGreetings");
            crate::ai_util::BotDoChat(ctx, bs, sect.as_ptr() as *mut c_char, 0);
        }

        qtrue
    }
}

/// Raven `BotAIShutdownClient`.
///
/// Source: `oracle/codemp/game/ai_main.c:891-914`
pub fn BotAIShutdownClient(ctx: GameContext<'_>, client: c_int, restart: qboolean) -> c_int {
    unsafe {
        let world = ctx.world;
        let bs = (*world).globals.botstates[client as usize];
        if bs.is_null() || (*bs).inuse == qfalse {
            return qfalse;
        }

        trap::BotFreeMoveState(ctx.engine, BotlibAiFreeMoveStateArgs::new((*bs).ms));
        // free the goal state
        trap::BotFreeGoalState(ctx.engine, BotlibAiFreeGoalStateArgs::new((*bs).gs));
        // free the weapon weights
        trap::BotFreeWeaponState(ctx.engine, BotlibAiFreeWeaponStateArgs::new((*bs).ws));
        // clear the bot state
        // Byte-wise, like C's memset: `bs` comes from B_Alloc/BG_Alloc's 4-byte
        // bump allocator, not guaranteed 8-aligned for bot_state_t's pointer fields.
        core::ptr::write_bytes(bs as *mut u8, 0, core::mem::size_of::<bot_state_t>());
        // set the inuse flag to qfalse
        (*bs).inuse = qfalse;
        // there's one bot less
        (*world).globals.numbots -= 1;
        qtrue
    }
}

/// Raven `BotResetState`.
///
/// `settings`/`cur_ps` are `Copy`, so the save/zero/restore mirrors Raven's
/// memcpy+memset+memcpy exactly.
///
/// Source: `oracle/codemp/game/ai_main.c:924-959`
pub fn BotResetState(ctx: GameContext<'_>, bs: *mut bot_state_t) {
    unsafe {
        // Save the things that must survive the reset.
        let settings = core::ptr::read(&(*bs).settings);
        let ps = core::ptr::read(&(*bs).cur_ps);
        let inuse = (*bs).inuse;
        let client = (*bs).client;
        let entitynum = (*bs).entitynum;
        let movestate = (*bs).ms;
        let goalstate = (*bs).gs;
        let weaponstate = (*bs).ws;
        let entergame_time = (*bs).entergame_time;
        // Reset the whole state.
        // Byte-wise: `bs` is B_Alloc/BG_Alloc pool storage (4-byte aligned only),
        // not guaranteed 8-aligned for bot_state_t's pointer fields.
        core::ptr::write_bytes(bs as *mut u8, 0, core::mem::size_of::<bot_state_t>());
        // Copy back the preserved state.
        (*bs).ms = movestate;
        (*bs).gs = goalstate;
        (*bs).ws = weaponstate;
        core::ptr::write(&mut (*bs).cur_ps, ps);
        core::ptr::write(&mut (*bs).settings, settings);
        (*bs).inuse = inuse;
        (*bs).client = client;
        (*bs).entitynum = entitynum;
        (*bs).entergame_time = entergame_time;
        // Reset several engine-side states.
        if (*bs).ms != 0 {
            trap::BotResetMoveState(ctx.engine, BotlibAiResetMoveStateArgs::new((*bs).ms));
        }
        if (*bs).gs != 0 {
            trap::BotResetGoalState(ctx.engine, BotlibAiResetGoalStateArgs::new((*bs).gs));
        }
        if (*bs).ws != 0 {
            trap::BotResetWeaponState(ctx.engine, BotlibAiResetWeaponStateArgs::new((*bs).ws));
        }
        if (*bs).gs != 0 {
            trap::BotResetAvoidGoals(ctx.engine, BotlibAiResetAvoidGoalsArgs::new((*bs).gs));
        }
        if (*bs).ms != 0 {
            trap::BotResetAvoidReach(ctx.engine, BotlibAiResetAvoidReachArgs::new((*bs).ms));
        }
    }
}

/// Raven `BotAILoadMap`.
///
/// Source: `oracle/codemp/game/ai_main.c:966-977`
pub fn BotAILoadMap(ctx: GameContext<'_>, restart: c_int) -> c_int {
    unsafe {
        let world = ctx.world;
        for i in 0..MAX_CLIENTS {
            let bi = (*world).globals.botstates[i];
            if !bi.is_null() && (*bi).inuse != qfalse {
                BotResetState(ctx, bi);
                (*bi).setupcount = 4;
            }
        }
        qtrue
    }
}

/// Raven `OrgVisible`.
///
/// `org1`/`org2` are read-only trace endpoints (never written), so they stay
/// by-value `vec3_t`.
///
/// Source: `oracle/codemp/game/ai_main.c:982-994`
pub fn OrgVisible(ctx: GameContext<'_>, org1: vec3_t, org2: vec3_t, ignore: c_int) -> c_int {
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        trap::Trace(
            ctx.engine,
            GTraceArgs::new(
                &mut tr,
                &org1,
                core::ptr::null(),
                core::ptr::null(),
                &org2,
                ignore,
                MASK_SOLID,
            ),
        );
        if tr.fraction == 1.0 {
            return 1;
        }
    }
    0
}

/// Raven `WPOrgVisible`.
///
/// Source: `oracle/codemp/game/ai_main.c:997-1026`
pub fn WPOrgVisible(
    ctx: GameContext<'_>,
    bot: *mut gentity_t,
    org1: vec3_t,
    org2: vec3_t,
    ignore: c_int,
) -> c_int {
    unsafe {
        let world = ctx.world;
        let base = (*world).g_entities.as_mut_ptr();
        let mut tr: trace_t = core::mem::zeroed();

        trap::Trace(
            ctx.engine,
            GTraceArgs::new(
                &mut tr,
                &org1,
                core::ptr::null(),
                core::ptr::null(),
                &org2,
                ignore,
                MASK_SOLID,
            ),
        );

        if tr.fraction == 1.0 {
            trap::Trace(
                ctx.engine,
                GTraceArgs::new(
                    &mut tr,
                    &org1,
                    core::ptr::null(),
                    core::ptr::null(),
                    &org2,
                    ignore,
                    MASK_PLAYERSOLID,
                ),
            );

            if tr.fraction != 1.0
                && (tr.entityNum as c_int) != ENTITYNUM_NONE
                && (*base.add(tr.entityNum as usize)).s.eType == ET_SPECIAL as c_int
            {
                let hitent = base.add(tr.entityNum as usize);
                if (*hitent).parent.is_some()
                    && !(*crate::ent_id::resolve(base, (*hitent).parent))
                        .client
                        .is_null()
                {
                    let ownent = crate::ent_id::resolve(base, (*hitent).parent);

                    if OnSameTeam(ctx, bot, ownent) != qfalse
                        || (*bot).s.number == (*ownent).s.number
                    {
                        return 1;
                    }
                }
                return 2;
            }

            return 1;
        }

        0
    }
}

/// Raven `OrgVisibleBox`.
///
/// Source: `oracle/codemp/game/ai_main.c:1029-1048`
pub fn OrgVisibleBox(
    ctx: GameContext<'_>,
    org1: vec3_t,
    mins: vec3_t,
    maxs: vec3_t,
    org2: vec3_t,
    ignore: c_int,
) -> c_int {
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        if (*ctx.world).cvars.g_RMG.integer != 0 {
            trap::Trace(
                ctx.engine,
                GTraceArgs::new(
                    &mut tr,
                    &org1,
                    core::ptr::null(),
                    core::ptr::null(),
                    &org2,
                    ignore,
                    MASK_SOLID,
                ),
            );
        } else {
            trap::Trace(
                ctx.engine,
                GTraceArgs::new(&mut tr, &org1, &mins, &maxs, &org2, ignore, MASK_SOLID),
            );
        }
        if tr.fraction == 1.0 && tr.startsolid == 0 && tr.allsolid == 0 {
            return 1;
        }
    }
    0
}

/// Raven `CheckForFunc`.
///
/// Source: `oracle/codemp/game/ai_main.c:1053-1083`
pub fn CheckForFunc(ctx: GameContext<'_>, org: vec3_t, ignore: c_int) -> c_int {
    unsafe {
        let world = &*ctx.world;
        let mut under = org;
        under[2] -= 64.0;

        let mut tr: trace_t = core::mem::zeroed();
        trap::Trace(
            ctx.engine,
            GTraceArgs::new(
                &mut tr,
                &org,
                core::ptr::null(),
                core::ptr::null(),
                &under,
                ignore,
                MASK_SOLID,
            ),
        );

        if tr.fraction == 1.0 {
            return 0;
        }

        let fent = &world.g_entities[tr.entityNum as usize];
        // Raven `if (!fent)` on `&g_entities[...]` is structurally dead. Raven
        // then `strstr(fent->classname, ...)` and would deref a null classname
        // (UB); guarding null is the one defined behavior here.
        if !fent.classname.is_null() {
            let cn = core::ffi::CStr::from_ptr(fent.classname);
            if cn.to_bytes().windows(5).any(|w| w == b"func_") {
                return 1; // there's a func brush here
            }
        }
    }
    0
}

/// Raven `BotPVSCheck`.
///
/// Source: `oracle/codemp/game/ai_main.c:1086-1101`
pub fn BotPVSCheck(ctx: GameContext<'_>, p1: vec3_t, p2: vec3_t) -> qboolean {
    // PORT-NOTE(bot_pvstype): the `bot_pvstype` cvar has no ported home yet
    // (ungrouped bot cvar); referenced as cited and reported as missing.
    unsafe {
        if (*ctx.world).cvars.g_RMG.integer != 0 && (*ctx.world).cvars.bot_pvstype.integer != 0 {
            let mut subPoint: vec3_t = [0.0; 3];
            crate::q_math::_VectorSubtract(p1, p2, &mut subPoint);

            if crate::q_math::VectorLength(subPoint) > 5000.0 {
                return qfalse;
            }
            return qtrue;
        }

        trap::InPVS(ctx.engine, GInPvsArgs::new(&p1, &p2))
    }
}

/// Raven `GetNearestVisibleWP`.
///
/// Source: `oracle/codemp/game/ai_main.c:1104-1149`
pub fn GetNearestVisibleWP(ctx: GameContext<'_>, org: vec3_t, ignore: c_int) -> c_int {
    unsafe {
        let world = ctx.world;
        let mut i: c_int = 0;
        let mut bestdist: f32 = if (*world).cvars.g_RMG.integer != 0 {
            300.0
        } else {
            // don't trace over 800 units away to avoid GIANT HORRIBLE SPEED HITS
            800.0
        };
        let mut bestindex: c_int = -1;

        let mins: vec3_t = [-15.0, -15.0, -1.0];
        let maxs: vec3_t = [15.0, 15.0, 1.0];

        while i < (*world).globals.gWPNum {
            let wp = (*world).globals.gWPArray.0[i as usize];
            if !wp.is_null() && (*wp).inuse != 0 {
                let mut a: vec3_t = [0.0; 3];
                crate::q_math::_VectorSubtract(org, (*wp).origin, &mut a);
                let flLen = crate::q_math::VectorLength(a);

                if flLen < bestdist
                    && ((*world).cvars.g_RMG.integer != 0
                        || BotPVSCheck(ctx, org, (*wp).origin) != qfalse)
                    && OrgVisibleBox(ctx, org, mins, maxs, (*wp).origin, ignore) != 0
                {
                    bestdist = flLen;
                    bestindex = i;
                }
            }

            i += 1;
        }

        bestindex
    }
}

/// Raven `PassWayCheck`.
///
/// Source: `oracle/codemp/game/ai_main.c:1157-1190`
pub fn PassWayCheck(ctx: GameContext<'_>, bs: *mut bot_state_t, windex: c_int) -> c_int {
    unsafe {
        let world = ctx.world;
        let wp = (*world).globals.gWPArray.0[windex as usize];
        if wp.is_null() || (*wp).inuse == 0 {
            // bad point index
            return 0;
        }

        if (*world).cvars.g_RMG.integer != 0 {
            if (*wp).flags & WPFLAG_RED_FLAG != 0 || (*wp).flags & WPFLAG_BLUE_FLAG != 0 {
                // red or blue flag, we'd like to get here
                return 1;
            }
        }

        if (*bs).wpDirection != 0 && (*wp).flags & WPFLAG_ONEWAY_FWD != 0 {
            return 0;
        } else if (*bs).wpDirection == 0 && (*wp).flags & WPFLAG_ONEWAY_BACK != 0 {
            return 0;
        }

        if !(*bs).wpCurrent.is_null()
            && (*wp).forceJumpTo != 0
            && (*wp).origin[2] > ((*(*bs).wpCurrent).origin[2] + 64.0)
            && (*bs).cur_ps.fd.forcePowerLevel[FP_LEVITATION as usize] < (*wp).forceJumpTo
        {
            // waypoint requires force jump level greater than our current one to pass
            return 0;
        }

        1
    }
}

/// Raven `TotalTrailDistance`.
///
/// Source: `oracle/codemp/game/ai_main.c:1193-1259`
pub fn TotalTrailDistance(
    ctx: GameContext<'_>,
    start: c_int,
    end: c_int,
    bs: *mut bot_state_t,
) -> f32 {
    unsafe {
        let world = ctx.world;
        let mut distancetotal: f32 = 0.0;

        let beginat: c_int;
        let endat: c_int;
        if start > end {
            beginat = end;
            endat = start;
        } else {
            beginat = start;
            endat = end;
        }

        let mut b = beginat;
        while b < endat {
            let p = (*world).globals.gWPArray.0[b as usize];
            if b >= (*world).globals.gWPNum || p.is_null() || (*p).inuse == 0 {
                // invalid waypoint index
                return -1.0;
            }

            if (*world).cvars.g_RMG.integer == 0 {
                if (end > start && (*p).flags & WPFLAG_ONEWAY_BACK != 0)
                    || (start > end && (*p).flags & WPFLAG_ONEWAY_FWD != 0)
                {
                    // a one-way point, this path cannot be travelled to the final point
                    return -1.0;
                }
            }

            distancetotal += (*p).disttonext;

            b += 1;
        }

        distancetotal
    }
}

/// Raven `CheckForShorterRoutes`.
///
/// Source: `oracle/codemp/game/ai_main.c:1263-1349`
pub fn CheckForShorterRoutes(ctx: GameContext<'_>, bs: *mut bot_state_t, newwpindex: c_int) {
    // PORT-NOTE(FORCEJUMP_INSTANTMETHOD): undefined in this build; the
    // non-instant force-jump branch is ported.
    unsafe {
        let world = ctx.world;
        let mut i: c_int = 0;
        let mut fj: c_int = 0;

        if (*bs).wpDestination.is_null() {
            return;
        }

        // set our traversal direction based on the index of the point
        if newwpindex < (*(*bs).wpDestination).index {
            (*bs).wpDirection = 0;
        } else if newwpindex > (*(*bs).wpDestination).index {
            (*bs).wpDirection = 1;
        }

        // can't switch again yet
        if (*bs).wpSwitchTime > (*world).level.time as f32 {
            return;
        }

        let cur = (*world).globals.gWPArray.0[newwpindex as usize];
        // no neighboring points to check off of
        if (*cur).neighbornum == 0 {
            return;
        }

        // get the trail distance for our wp
        let mut bestindex = newwpindex;
        let mut bestlen = TotalTrailDistance(ctx, newwpindex, (*(*bs).wpDestination).index, bs);

        while i < (*cur).neighbornum {
            // now go through the neighbors and check the distance to the desired point
            let checklen = TotalTrailDistance(
                ctx,
                (*cur).neighbors[i as usize].num,
                (*(*bs).wpDestination).index,
                bs,
            );

            if checklen < bestlen - 64.0 || bestlen == -1.0 {
                // this path covers less distance, let's take it instead
                if (*bs).cur_ps.fd.forcePowerLevel[FP_LEVITATION as usize]
                    >= (*cur).neighbors[i as usize].forceJumpTo
                {
                    bestlen = checklen;
                    bestindex = (*cur).neighbors[i as usize].num;

                    if (*cur).neighbors[i as usize].forceJumpTo != 0 {
                        fj = (*cur).neighbors[i as usize].forceJumpTo;
                    } else {
                        fj = 0;
                    }
                }
            }

            i += 1;
        }

        if bestindex != newwpindex && bestindex != -1 {
            // we found a path we want to switch to, let's do it
            (*bs).wpCurrent = (*world).globals.gWPArray.0[bestindex as usize];
            (*bs).wpSwitchTime = ((*world).level.time + 3000) as f32;

            if fj != 0 {
                // do we have to force jump to get to this neighbor?
                (*bs).forceJumpChargeTime = (*world).level.time + 1000;
                (*bs).beStill = ((*world).level.time + 1000) as f32;
                (*bs).forceJumping = (*bs).forceJumpChargeTime as f32;
            }
        }
    }
}

/// Raven `WPConstantRoutine`.
///
/// Source: `oracle/codemp/game/ai_main.c:1353-1429`
pub fn WPConstantRoutine(ctx: GameContext<'_>, bs: *mut bot_state_t) {
    // PORT-NOTE(forceJumpStrength/FORCEJUMP_INSTANTMETHOD): `forceJumpStrength`
    // has no ported home yet (reported missing); the instant-method macro is
    // undefined here, so the non-instant branches are ported.
    unsafe {
        let world = ctx.world;
        let lt = (*world).level.time;
        if (*bs).wpCurrent.is_null() {
            return;
        }

        if (*(*bs).wpCurrent).flags & WPFLAG_DUCK != 0 {
            // duck while travelling to this point
            (*bs).duckTime = (lt + 100) as f32;
        }

        // #ifndef FORCEJUMP_INSTANTMETHOD
        if (*(*bs).wpCurrent).flags & WPFLAG_JUMP != 0 {
            // jump while travelling to this point
            let mut heightDif: f32 = (*(*bs).wpCurrent).origin[2] - (*bs).origin[2] + 16.0;

            if (*bs).origin[2] + 16.0 >= (*(*bs).wpCurrent).origin[2] {
                // don't need to jump, we're already higher than this point
                heightDif = 0.0;
            }

            if heightDif > 40.0
                && ((*bs).cur_ps.fd.forcePowersKnown & (1 << (FP_LEVITATION as c_int))) != 0
                && ((*bs).cur_ps.fd.forceJumpCharge
                    < (forceJumpStrength
                        [(*bs).cur_ps.fd.forcePowerLevel[FP_LEVITATION as usize] as usize]
                        - 100.0)
                    || (*bs).cur_ps.groundEntityNum == ENTITYNUM_NONE)
            {
                // alright, let's jump
                (*bs).forceJumpChargeTime = lt + 1000;
                if (*bs).cur_ps.groundEntityNum != ENTITYNUM_NONE
                    && (*bs).jumpPrep < (lt - 300) as f32
                {
                    (*bs).jumpPrep = (lt + 700) as f32;
                }
                (*bs).beStill = (lt + 300) as f32;
                (*bs).jumpTime = 0.0;

                if (*bs).wpSeenTime < (lt + 600) as f32 {
                    (*bs).wpSeenTime = (lt + 600) as f32;
                }
            } else if heightDif > 64.0
                && ((*bs).cur_ps.fd.forcePowersKnown & (1 << (FP_LEVITATION as c_int))) == 0
            {
                // this point needs force jump to reach and we don't have it
                // Kill the current point and turn around
                (*bs).wpCurrent = core::ptr::null_mut();
                if (*bs).wpDirection != 0 {
                    (*bs).wpDirection = 0;
                } else {
                    (*bs).wpDirection = 1;
                }

                return;
            }
        }
        // #endif

        if (*(*bs).wpCurrent).forceJumpTo != 0 {
            // #else branch (FORCEJUMP_INSTANTMETHOD undefined)
            let mut heightDif: f32 = (*(*bs).wpCurrent).origin[2] - (*bs).origin[2] + 16.0;

            if (*bs).origin[2] + 16.0 >= (*(*bs).wpCurrent).origin[2] {
                heightDif = 0.0;
            }

            if (*bs).cur_ps.fd.forceJumpCharge
                < (forceJumpStrength
                    [(*bs).cur_ps.fd.forcePowerLevel[FP_LEVITATION as usize] as usize]
                    - 100.0)
            {
                (*bs).forceJumpChargeTime = lt + 200;
            }
        }
    }
}

/// Raven `BotCTFGuardDuty`.
///
/// Source: `oracle/codemp/game/ai_main.c:1432-1446`
pub fn BotCTFGuardDuty(ctx: GameContext<'_>, bs: *mut bot_state_t) -> qboolean {
    unsafe {
        let gt = (*ctx.world).cvars.g_gametype.integer;
        if gt != GT_CTF && gt != GT_CTY {
            return qfalse;
        }
        if (*bs).ctfState == bot_ctf_state_t::CTFSTATE_DEFENDER as c_int {
            return qtrue;
        }
    }
    qfalse
}

/// Raven `WPTouchRoutine`.
///
/// Source: `oracle/codemp/game/ai_main.c:1452-1539`
pub fn WPTouchRoutine(ctx: GameContext<'_>, bs: *mut bot_state_t) {
    // PORT-NOTE(FORCEJUMP_INSTANTMETHOD): instant-method macro undefined here.
    unsafe {
        let world = ctx.world;
        let lt = (*world).level.time;

        if (*bs).wpCurrent.is_null() {
            return;
        }

        (*bs).wpTravelTime = (lt + 10000) as f32;

        if (*(*bs).wpCurrent).flags & WPFLAG_NOMOVEFUNC != 0 {
            // don't try to use any nearby map objects for a little while
            (*bs).noUseTime = lt + 4000;
        }

        // #ifndef FORCEJUMP_INSTANTMETHOD
        if (*(*bs).wpCurrent).flags & WPFLAG_JUMP != 0 && (*(*bs).wpCurrent).forceJumpTo == 0 {
            // jump if we're flagged to but not if this indicates a force jump point
            (*bs).jumpTime = (lt + 100) as f32;
        }
        // #endif

        if (*bs).isCamper != 0
            && (*world).cvars.bot_camp.integer != 0
            && (BotIsAChickenWuss(ctx, bs) != 0
                || BotCTFGuardDuty(ctx, bs) != qfalse
                || (*bs).isCamper == 2)
            && ((*(*bs).wpCurrent).flags & WPFLAG_SNIPEORCAMP != 0
                || (*(*bs).wpCurrent).flags & WPFLAG_SNIPEORCAMPSTAND != 0)
            && (*bs).cur_ps.weapon != WP_SABER
            && (*bs).cur_ps.weapon != WP_MELEE
            && (*bs).cur_ps.weapon != WP_STUN_BATON
        {
            // if we're a camper and a chicken then camp
            let lastNum: c_int = if (*bs).wpDirection != 0 {
                (*(*bs).wpCurrent).index + 1
            } else {
                (*(*bs).wpCurrent).index - 1
            };

            let lp = (*world).globals.gWPArray.0[lastNum as usize];
            if !lp.is_null() && (*lp).inuse != 0 && (*lp).index != 0 && (*bs).isCamping < lt as f32
            {
                (*bs).isCamping = (lt + (*world).bg_state.rng.rand() % 15000 + 30000) as f32;
                (*bs).wpCamping = (*bs).wpCurrent;
                (*bs).wpCampingTo = lp;

                if (*(*bs).wpCurrent).flags & WPFLAG_SNIPEORCAMPSTAND != 0 {
                    (*bs).campStanding = qtrue;
                } else {
                    (*bs).campStanding = qfalse;
                }
            }
        } else if ((*bs).cur_ps.weapon == WP_SABER
            || (*bs).cur_ps.weapon == WP_STUN_BATON
            || (*bs).cur_ps.weapon == WP_MELEE)
            && (*bs).isCamping > lt as f32
        {
            // don't snipe/camp with a melee weapon, that would be silly
            (*bs).isCamping = 0.0;
            (*bs).wpCampingTo = core::ptr::null_mut();
            (*bs).wpCamping = core::ptr::null_mut();
        }

        if !(*bs).wpDestination.is_null() {
            if (*(*bs).wpCurrent).index == (*(*bs).wpDestination).index {
                (*bs).wpDestination = core::ptr::null_mut();

                if (*bs).runningLikeASissy != 0 {
                    // scared and running, keep navigational priorities less delayed
                    (*bs).destinationGrabTime = (lt + 500) as f32;
                } else {
                    (*bs).destinationGrabTime = (lt + 3500) as f32;
                }
            } else {
                CheckForShorterRoutes(ctx, bs, (*(*bs).wpCurrent).index);
            }
        }
    }
}

